var i=[{title:`Pornește de la obiectiv`,text:`Fiecare mișcare are o sarcină: o genuflexiune antrenează împreună extensia șoldului și a genunchiului, un ramat antrenează tragerea, iar o balansare din șold lucrează mai ales prin șolduri. O tehnică bună poate arăta puțin diferit de la o persoană la alta, deoarece lungimea membrelor, mobilitatea și echipamentul variază. Contează controlul sigur și repetabil. Nimeni nu trebuie să se potrivească unui singur aspect exact.`},{title:`Construiește fundația`,text:`Învață mai întâi o variantă fără sarcină sau cu sarcină ușoară. Folosește o amplitudine pe care o poți controla, repetări line și sprijin stabil când ai nevoie. Apoi progresează în pași mici: mai multe repetări, mai multă rezistență sau o variantă mai complexă. Filmarea sau lucrul cu un antrenor calificat pot dezvălui obiceiuri, dar un video singur nu poate diagnostica o accidentare.`},{title:`Când forma se strică`,text:`Semnele de alarmă în timpul unei serii includ pierderea echilibrului, coborârea greutății fără control, abaterea de la traseul dorit sau compensările care se agravează pe măsură ce obosești. Oprește-te sau fă exercițiul mai ușor când le observi. Ridicarea mai grea cu o tehnică ce se prăbușește nu înseamnă progres.`},{title:`Exemplu`,text:`Înainte să încarci un îndreptat românesc cu gantere, exersează balansarea din șold cu mâinile pe șolduri, apoi cu o greutate ușoară. Adaugă greutate doar când șoldurile se duc în spate sub control, iar poziția spatelui rămâne aceeași de la o repetare la alta, pentru corpul tău.`},{title:`Folosirea TrainUp`,text:`Planul tău alege exerciții care se potrivesc cu nivelul și coordonarea ta, iar fiecare pagină de exercițiu din Explorează are pași și note de tehnică. TrainUp nu prescrie greutăți, așa că tu alegi sarcina. Notează-ți repetările în timpul antrenamentului și evaluează-ți efortul după aceea și adaugă sarcină în pași mici, fără să urmărești un record în fiecare sesiune.`}];var r=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Ghid practic ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var t={sections:i,sources:r};export{t as default,i as sections,r as sources};